package com.collegeerp.erp.attendance.service;
import com.collegeerp.erp.academic.entity.AcademicModels.*; import com.collegeerp.erp.attendance.dto.AttendanceDtos.*; import com.collegeerp.erp.attendance.entity.AttendanceModels.*; import com.collegeerp.erp.attendance.repository.*; import com.collegeerp.erp.auth.security.SecurityUtils; import com.collegeerp.erp.college.entity.College; import com.collegeerp.erp.common.exception.*; import com.collegeerp.erp.student.entity.StudentProfile; import com.collegeerp.erp.timetable.entity.TimetableModels.TimetableEntry; import com.collegeerp.erp.user.entity.User;
import jakarta.persistence.EntityManager; import jakarta.transaction.Transactional; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*;
import com.collegeerp.erp.attendance.util.SimplePdfExporter;
@Service public class AttendanceService {
 private final EntityManager em;private final AttendanceSessionRepository sessions;private final StudentAttendanceRepository attendance;private final AttendanceCorrectionRepository corrections;private final AuditLogRepository audits;private final double threshold;
 public AttendanceService(EntityManager em,AttendanceSessionRepository s,StudentAttendanceRepository a,AttendanceCorrectionRepository c,AuditLogRepository l,@Value("${app.attendance.minimum-percentage:75}")double threshold){this.em=em;sessions=s;attendance=a;corrections=c;audits=l;this.threshold=threshold;}
 private Long tenant(){Long id=SecurityUtils.requireCurrentUser().getCollegeId();if(id==null)throw new BadRequestException("Institution is required");return id;}private User actor(){return em.getReference(User.class,SecurityUtils.getCurrentUserId());}private AttendanceSession session(Long id){return sessions.findByIdAndCollegeId(id,tenant()).orElseThrow(()->new ResourceNotFoundException("Attendance session not found"));}
 public List<SessionResponse> list(LocalDate from,LocalDate to){return sessions.findByCollegeIdAndSessionDateBetweenOrderBySessionDateAsc(tenant(),from,to).stream().filter(this::canView).map(this::map).toList();}
 @Transactional public SessionResponse createDaily(DailySessionRequest r){if(!LocalDate.now().equals(r.date()))throw new BadRequestException("Attendance sessions can be created only for today's date");AcademicClass clazz=owned(AcademicClass.class,r.classId());Section section=owned(Section.class,r.sectionId());User teacher=ownedUser(r.teacherId());AttendanceSession s=new AttendanceSession();s.setCollege(em.getReference(College.class,tenant()));s.setSessionDate(r.date());s.setType(SessionType.DAILY);s.setAssignedTeacher(teacher);s.setLockAt(r.date().atTime(23,59).plusHours(r.lockAfterHours()==null?0:r.lockAfterHours()));sessions.save(s);audit("CREATE","AttendanceSession",s.getId(),"Daily session for "+clazz.getName()+"/"+section.getName());return map(s);}
 @Transactional public SessionResponse submit(Long id,SubmitRequest r){AttendanceSession s=session(id);if(!LocalDate.now().equals(s.getSessionDate()))throw new BadRequestException("Attendance can be submitted only for today's date");requireMarkPermission(s);if(s.getStatus()==SessionStatus.LOCKED||LocalDateTime.now().isAfter(s.getLockAt())){s.setStatus(SessionStatus.LOCKED);throw new BadRequestException("Attendance deadline has passed");}Set<Long> seen=new HashSet<>();for(MarkItem item:r.attendance()){if(!seen.add(item.studentId()))throw new BadRequestException("Duplicate student in attendance submission");StudentProfile student=em.find(StudentProfile.class,item.studentId());if(student==null||!tenant().equals(student.getCollege().getId())||!isEnrolled(s,student.getId()))throw new BadRequestException("Student is not enrolled in this session class");if(attendance.findByCollegeIdAndSessionIdAndStudentId(tenant(),id,item.studentId()).isPresent())throw new BadRequestException("Attendance already exists for student");StudentAttendance a=new StudentAttendance();a.setCollege(s.getCollege());a.setSession(s);a.setStudent(student);a.setStatus(parse(item.status()));a.setRemarks(item.remarks());a.setMarkedBy(actor());a.setMarkedAt(LocalDateTime.now());attendance.save(a);if(a.getStatus()==AttendanceStatus.ABSENT||a.getStatus()==AttendanceStatus.LATE)audit("NOTIFY","StudentAttendance",a.getId(),"Absence/late notification queued for student and parent");}s.setStatus(SessionStatus.SUBMITTED);s.setSubmittedAt(LocalDateTime.now());s.setSubmittedBy(actor());audit("SUBMIT","AttendanceSession",id,"Manual attendance submitted");return map(s);}
 @Transactional public AttendanceItem correct(Long attendanceId,CorrectionRequest r){StudentAttendance a=attendance.findByIdAndCollegeId(attendanceId,tenant()).orElseThrow(()->new ResourceNotFoundException("Attendance not found"));requireMarkPermission(a.getSession());AttendanceStatus next=parse(r.status());AttendanceCorrection c=new AttendanceCorrection();c.setCollege(a.getCollege());c.setAttendance(a);c.setOldStatus(a.getStatus());c.setNewStatus(next);c.setReason(r.reason().trim());c.setCorrectedBy(actor());c.setCorrectedAt(LocalDateTime.now());corrections.save(c);a.setStatus(next);a.setMarkedBy(actor());a.setMarkedAt(LocalDateTime.now());audit("CORRECT","StudentAttendance",a.getId(),r.reason());return map(a);}
 public ReportResponse report(Long studentId,LocalDate from,LocalDate to){StudentProfile student=em.find(StudentProfile.class,studentId);if(student==null||!tenant().equals(student.getCollege().getId()))throw new ResourceNotFoundException("Student not found");if(SecurityUtils.hasRole("STUDENT")&&!student.getUser().getId().equals(SecurityUtils.getCurrentUserId()))throw new org.springframework.security.access.AccessDeniedException("Cannot view another student's attendance");List<StudentAttendance> rows=attendance.report(tenant(),studentId,from,to);long present=count(rows,AttendanceStatus.PRESENT),late=count(rows,AttendanceStatus.LATE),excused=count(rows,AttendanceStatus.EXCUSED),half=count(rows,AttendanceStatus.HALF_DAY);double earned=present+late+excused+half*.5;double pct=rows.isEmpty()?0:Math.round(earned*10000.0/rows.size())/100.0;return new ReportResponse(studentId,student.getFullName(),from,to,rows.size(),present,count(rows,AttendanceStatus.ABSENT),late,excused,half,count(rows,AttendanceStatus.LEAVE),pct,pct<threshold);}
 public byte[] exportExcel(Long studentId,LocalDate from,LocalDate to){ReportResponse r=report(studentId,from,to);String collegeName=em.find(College.class,tenant()).getName();String xml="<?xml version=\"1.0\"?><Workbook xmlns=\"urn:schemas-microsoft-com:office:spreadsheet\" xmlns:ss=\"urn:schemas-microsoft-com:office:spreadsheet\" xmlns:x=\"urn:schemas-microsoft-com:office:excel\"><Styles><Style ss:ID=\"Title\"><Alignment ss:Horizontal=\"Center\"/><Font ss:Bold=\"1\" ss:Size=\"16\" ss:Color=\"#1E3A8A\"/></Style><Style ss:ID=\"College\"><Alignment ss:Horizontal=\"Center\"/><Font ss:Bold=\"1\" ss:Size=\"14\" ss:Color=\"#FFFFFF\"/><Interior ss:Color=\"#2563EB\" ss:Pattern=\"Solid\"/></Style><Style ss:ID=\"Report\"><Alignment ss:Horizontal=\"Center\"/><Font ss:Bold=\"1\" ss:Size=\"13\"/></Style><Style ss:ID=\"Header\"><Font ss:Bold=\"1\" ss:Color=\"#FFFFFF\"/><Interior ss:Color=\"#2563EB\" ss:Pattern=\"Solid\"/><Borders><Border ss:Position=\"Bottom\" ss:LineStyle=\"Continuous\" ss:Weight=\"1\"/></Borders></Style><Style ss:ID=\"Label\"><Font ss:Bold=\"1\"/><Interior ss:Color=\"#EFF6FF\" ss:Pattern=\"Solid\"/></Style><Style ss:ID=\"Value\"><Borders><Border ss:Position=\"Bottom\" ss:LineStyle=\"Continuous\" ss:Weight=\"1\" ss:Color=\"#E2E8F0\"/></Borders></Style></Styles><Worksheet ss:Name=\"Attendance Report\"><Table><Column ss:Width=\"180\"/><Column ss:Width=\"250\"/>"+titleRow("COLLEGE ERP GROUP OF INSTITUTES","Title")+titleRow(collegeName.toUpperCase(Locale.ROOT),"College")+titleRow("STUDENT ATTENDANCE REPORT","Report")+row("Generated On",LocalDateTime.now().toString())+row("Metric","Value","Header")+row("Student",r.studentName())+row("Reporting Period",r.from()+" to "+r.to())+row("Total Lectures",r.total())+row("Present",r.present())+row("Absent",r.absent())+row("Late",r.late())+row("Excused",r.excused())+row("Half Day",r.halfDay())+row("Leave",r.leave())+row("Attendance Percentage",r.percentage()+"%")+"</Table><WorksheetOptions xmlns=\"urn:schemas-microsoft-com:office:excel\"><FreezePanes/><FrozenNoSplit/><SplitHorizontal>5</SplitHorizontal><TopRowBottomPane>5</TopRowBottomPane><FitToPage/><PageSetup><Layout x:Orientation=\"Portrait\"/></PageSetup></WorksheetOptions></Worksheet></Workbook>";return xml.getBytes(StandardCharsets.UTF_8);}
 public byte[] exportPdf(Long studentId,LocalDate from,LocalDate to){ReportResponse r=report(studentId,from,to);String collegeName=em.find(College.class,tenant()).getName();return SimplePdfExporter.create(List.of(collegeName,"Attendance report","Student: "+r.studentName(),"Period: "+from+" to "+to,"Total: "+r.total(),"Present: "+r.present(),"Absent: "+r.absent(),"Attendance: "+r.percentage()+"%"));}
 private String titleRow(Object value,String style){return "<Row ss:Height=\"26\"><Cell ss:StyleID=\""+style+"\" ss:MergeAcross=\"1\"><Data ss:Type=\"String\">"+esc(String.valueOf(value))+"</Data></Cell></Row>";}private String row(Object a,Object b){return row(a,b,null);}private String row(Object a,Object b,String style){String first=style==null?"Label":style,second=style==null?"Value":style;return "<Row><Cell ss:StyleID=\""+first+"\"><Data ss:Type=\"String\">"+esc(String.valueOf(a))+"</Data></Cell><Cell ss:StyleID=\""+second+"\"><Data ss:Type=\"String\">"+esc(String.valueOf(b))+"</Data></Cell></Row>";}private String esc(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
 private boolean canView(AttendanceSession s){if(SecurityUtils.hasRole("STUDENT"))return s.getTimetableEntry()!=null&&isEnrolled(s,em.createQuery("select p.id from StudentProfile p where p.user.id=:u and p.college.id=:c",Long.class).setParameter("u",SecurityUtils.getCurrentUserId()).setParameter("c",tenant()).getSingleResult());return !SecurityUtils.hasRole("SUBJECT_TEACHER")&&!SecurityUtils.hasRole("CLASS_TEACHER")||s.getAssignedTeacher().getId().equals(SecurityUtils.getCurrentUserId())||isClassTeacher(s);}
 private void requireMarkPermission(AttendanceSession s){if(s.getAssignedTeacher().getId().equals(SecurityUtils.getCurrentUserId())||isClassTeacher(s))return;throw new org.springframework.security.access.AccessDeniedException("Attendance session is not assigned to you");}
 private boolean isClassTeacher(AttendanceSession s){if(s.getTimetableEntry()==null)return false;return em.createQuery("select count(a) from ManagedClassTeacherAssignment a where a.college.id=:c and a.teacher.id=:u and a.academicClass.id=:cl and a.section.id=:se",Long.class).setParameter("c",tenant()).setParameter("u",SecurityUtils.getCurrentUserId()).setParameter("cl",s.getTimetableEntry().getTimetable().getAcademicClass().getId()).setParameter("se",s.getTimetableEntry().getTimetable().getSection().getId()).getSingleResult()>0;}
 private boolean isEnrolled(AttendanceSession s,Long student){if(s.getTimetableEntry()==null)return true;return em.createQuery("select count(e) from ManagedStudentEnrollment e where e.college.id=:c and e.student.id=:st and e.academicClass.id=:cl and e.section.id=:se and e.active=true",Long.class).setParameter("c",tenant()).setParameter("st",student).setParameter("cl",s.getTimetableEntry().getTimetable().getAcademicClass().getId()).setParameter("se",s.getTimetableEntry().getTimetable().getSection().getId()).getSingleResult()>0;}
 private SessionResponse map(AttendanceSession s){TimetableEntry e=s.getTimetableEntry();List<AttendanceItem> items=new ArrayList<>(attendance.findByCollegeIdAndSessionId(tenant(),s.getId()).stream().map(this::map).toList());if(e!=null){Set<Long> marked=items.stream().map(AttendanceItem::studentId).collect(java.util.stream.Collectors.toSet());List<StudentProfile> roster=em.createQuery("select x.student from ManagedStudentEnrollment x where x.college.id=:c and x.academicClass.id=:cl and x.section.id=:se and x.active=true order by x.student.fullName",StudentProfile.class).setParameter("c",tenant()).setParameter("cl",e.getTimetable().getAcademicClass().getId()).setParameter("se",e.getTimetable().getSection().getId()).getResultList();roster.stream().filter(st->!marked.contains(st.getId())).forEach(st->items.add(new AttendanceItem(null,st.getId(),st.getAdmissionNumber(),st.getFullName(),null,null)));}return new SessionResponse(s.getId(),s.getSessionDate(),s.getType().name(),s.getStatus().name(),s.getLockAt(),s.getAssignedTeacher().getId(),s.getAssignedTeacher().getFullName(),e==null?"Daily":e.getTimetable().getAcademicClass().getName(),e==null?"":e.getTimetable().getSection().getName(),e==null||e.getSubject()==null?"Daily attendance":e.getSubject().getName(),items);}private AttendanceItem map(StudentAttendance a){return new AttendanceItem(a.getId(),a.getStudent().getId(),a.getStudent().getAdmissionNumber(),a.getStudent().getFullName(),a.getStatus().name(),a.getRemarks());}
 private AttendanceStatus parse(String s){try{AttendanceStatus status=AttendanceStatus.valueOf(s.toUpperCase(Locale.ROOT));if(status!=AttendanceStatus.PRESENT&&status!=AttendanceStatus.ABSENT)throw new IllegalArgumentException();return status;}catch(Exception e){throw new BadRequestException("Attendance status must be PRESENT or ABSENT");}}private long count(List<StudentAttendance> a,AttendanceStatus s){return a.stream().filter(x->x.getStatus()==s).count();}private User ownedUser(Long id){User u=em.find(User.class,id);if(u==null||u.getCollege()==null||!tenant().equals(u.getCollege().getId()))throw new ResourceNotFoundException("Teacher not found");return u;}private <T extends TenantEntity>T owned(Class<T> c,Long id){T x=em.find(c,id);if(x==null||!tenant().equals(x.getCollege().getId()))throw new ResourceNotFoundException(c.getSimpleName()+" not found");return x;}
 private void audit(String action,String entity,Long id,String details){AuditLog a=new AuditLog();a.setCollege(em.getReference(College.class,tenant()));a.setActor(actor());a.setAction(action);a.setEntityType(entity);a.setEntityId(id);a.setDetails(details);audits.save(a);}
}
